// page 是閱讀順序；source_page 是原文件頁碼。兩種來源不混用頁碼。
const sections = [
  {id:'rebar1',name:'概念與柱筋',range:[113,133],sourceRange:'第 113–133 頁',color:'#216a7b',desc:'基本概念、一般說明與柱筋圖說'},
  {id:'rebar2',name:'梁筋與板筋',range:[134,155],sourceRange:'第 134–155 頁',color:'#3d72a4',desc:'梁筋、板筋圖說與細部'},
  {id:'rebar3',name:'牆筋及開口補強',range:[156,163],sourceRange:'第 156–163 頁',color:'#7356a3',desc:'牆筋圖說與梁開口補強'},
  {id:'landscape',name:'景觀圖說',range:[164,177],sourceRange:'第 164–177 頁',color:'#3e7d4d',desc:'覆土、植栽、室外高程、鋪面排水與 RFI'},
  {id:'facademep',name:'帷幕與機電',range:[178,193],sourceRange:'第 178–193 頁',color:'#a16236',desc:'帷幕分格防水、設備維修與管線整合'},
  {id:'coordination',name:'跨專業整合',range:[194,220],sourceRange:'第 194–220 頁',color:'#a54d5a',desc:'五類套疊、三級檢核、衝突矩陣與 RFI 決策'}
];
const notes={landscape:'景觀高程與排水必須連回建築出入口及地下室頂板，避免積水與倒灌。',facademep:'帷幕、結構邊緣、天花與機電設備會互相影響，需用平面、剖面及節點一起套疊。',coordination:'衝突處理要標明圖號、版次、樓層、軸線與差異值，取得正式 RFI 回覆後才施工。'};
let active=sections[0],selectedPage=113,query='';
const $=s=>document.querySelector(s),nav=$('#sectionNav'),grid=$('#sectionGrid'),list=$('#topicList'),detail=$('#detailContent');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=p=>`第 ${p.page} 頁`;
const norm=s=>String(s??'').normalize('NFKC').toLowerCase().trim();
function meaningfulLines(p){return (p.lines||[]).map(x=>String(x).replace(/^[●□]\s*/, '').trim()).filter(x=>x&&!/^圖說基本認知[|｜]第二部分$/.test(x)&&x!=='識圖'&&!/^FUNCTIONAL BLOCK/.test(x));}
function cleanTitle(p){const lines=meaningfulLines(p);return (p.title||lines[0]||`第 ${p.page} 頁`).replace(/^第[一二三四五六七八九十]+區塊[:：]?\s*/,'').trim();}
function detailLines(p){const lines=meaningfulLines(p),title=cleanTitle(p);return lines.filter((x,i)=>!(i===0&&x===title));}
function pageImage(p){return p.image;}
function renderSections(){nav.innerHTML=sections.map((s,i)=>`<button class="nav-item ${s.id===active.id?'active':''}" data-id="${s.id}"><span>${i+1}</span>${esc(s.name)}</button>`).join('');grid.innerHTML=sections.map((s,i)=>`<button class="section-card ${s.id===active.id?'active':''}" style="--section-color:${s.color}" data-id="${s.id}"><span class="number">0${i+1} · ${esc(s.sourceRange)}</span><h3>${esc(s.name)}</h3><p>${esc(s.desc)}</p></button>`).join('');document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>selectSection(b.dataset.id));}
function selectSection(id){active=sections.find(s=>s.id===id);query='';$('#searchInput').value='';selectedPage=active.range[0];$('#topicHeading').textContent=active.name;$('#activeRange').textContent=active.sourceRange;renderSections();renderList();renderDetail();closeMenu();document.querySelector('.workspace').scrollIntoView({block:'start'});}
function currentPages(){const q=norm(query);if(/^\d+$/.test(q)){const n=Number(q);return window.PAGES.filter(p=>p.page===n)}return window.PAGES.filter(p=>q?norm(`${p.text} ${p.title} ${p.page} ${p.source_page} ${p.source_name}`).includes(q):p.page>=active.range[0]&&p.page<=active.range[1]);}
function renderList(){const pages=currentPages();$('#resultCount').textContent=`${pages.length} 頁`;list.innerHTML=pages.length?pages.map(p=>`<button class="topic-button ${p.page===selectedPage?'active':''}" data-page="${p.page}"><span class="page-badge">P.${p.page}</span><strong>${esc(cleanTitle(p))}</strong><small>›</small></button>`).join(''):'<div class="empty">找不到符合內容，換個關鍵字試試。</div>';document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{selectedPage=Number(b.dataset.page);renderList();renderDetail();if(innerWidth<1050)$('#detailPanel').scrollIntoView({block:'start'});});}
function renderDetail(){const p=window.PAGES.find(x=>x.page===selectedPage);if(!p){detail.innerHTML='<div class="empty">請先選擇一個頁面。</div>';return}const section=sections.find(s=>p.page>=s.range[0]&&p.page<=s.range[1])||active,bullets=detailLines(p),caption=label(p),note=notes[section.id]||'本頁文字由來源教材擷取，圖說、尺寸及註記請以原始頁面為準。';detail.innerHTML=`<div class="detail-hero"><div><p class="eyebrow">${esc(caption)} · ${esc(section.name)}</p><h2>${esc(cleanTitle(p))}</h2><p class="lead">${esc(bullets[0]||'本頁以圖面範例為主，請直接核對下方原始頁面。')}</p></div><div class="page-marker"><span>頁碼</span><b>${p.page}</b><small>／220</small></div></div><button class="pdf-page-view" id="enlargePage" aria-label="放大查看 ${esc(caption)}"><img src="${esc(pageImage(p))}" alt="${esc(caption)}原始內容"><span>點一下放大查看</span></button><div class="detail-block"><h3>${esc(caption)}內容整理</h3>${bullets.length?`<ul>${bullets.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>本頁主要呈現圖面或施工詳圖，請放大原頁逐項核對尺寸、標高、符號與註記。</p>'}</div><div class="detail-block caution"><h3>閱讀注意事項</h3><p>${esc(note)}</p></div><div class="page-actions"><button id="prevPage">← 上一頁</button><button id="nextPage">下一頁 →</button></div>`;$('#prevPage').onclick=()=>move(-1);$('#nextPage').onclick=()=>move(1);$('#enlargePage').onclick=()=>showPage(p);}
function showPage(p){const modal=document.createElement('div');modal.className='page-modal';modal.innerHTML=`<button class="modal-close" aria-label="關閉放大頁面">×</button><div><img src="${esc(pageImage(p))}" alt="${esc(label(p))}放大內容"><p>${esc(label(p))}／220</p></div>`;document.body.appendChild(modal);const previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';const key=e=>{if(e.key==='Escape')close()};const close=()=>{modal.remove();document.body.style.overflow=previousOverflow;document.removeEventListener('keydown',key)};modal.querySelector('.modal-close').onclick=close;modal.onclick=e=>{if(e.target===modal)close()};document.addEventListener('keydown',key);modal.querySelector('.modal-close').focus();}
function move(d){const pages=query?currentPages():window.PAGES,i=pages.findIndex(x=>x.page===selectedPage),p=pages[Math.max(0,Math.min(pages.length-1,i+d))];if(p){selectedPage=p.page;if(!query){active=sections.find(s=>p.page>=s.range[0]&&p.page<=s.range[1]);$('#topicHeading').textContent=active.name;$('#activeRange').textContent=active.sourceRange;renderSections();}renderList();renderDetail();}}
function search(){query=$('#searchInput').value.trim();if(!query){$('#topicHeading').textContent=active.name;selectedPage=active.range[0];renderList();renderDetail();return}const pages=currentPages();$('#topicHeading').textContent=`搜尋：${query}`;if(pages.length)selectedPage=pages[0].page;renderList();if(pages.length)renderDetail();else detail.innerHTML='<div class="empty">找不到符合內容，請嘗試其他關鍵字。</div>';document.querySelector('.workspace').scrollIntoView({block:'start'});}
$('#searchButton').onclick=search;$('#searchInput').addEventListener('keydown',e=>{if(e.key==='Enter')search()});function closeMenu(){$('#sidebar').classList.remove('open');$('#overlay').classList.remove('show')}$('#menuButton').onclick=()=>{$('#sidebar').classList.toggle('open');$('#overlay').classList.toggle('show')};$('#overlay').onclick=closeMenu;renderSections();renderList();renderDetail();
